CREATE TABLE IF NOT EXISTS corporate_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_code text UNIQUE NOT NULL, name text NOT NULL, category text NOT NULL, description text, asset_image_url text, serial_number text, acquisition_date date, acquisition_cost numeric(18,2), currency text DEFAULT 'NGN', current_value numeric(18,2), location text, custodian_name text, department text, condition text DEFAULT 'Good', status text DEFAULT 'Active', warranty_expiry date, disposal_date date, notes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());